#!/usr/bin/env python3
import sys, os, re, errno, stat, time, json, base64, subprocess, unicodedata, codecs
from dataclasses import dataclass, field

START_TIME = time.time()
VERSION = "ripgrep 14.1.1 (rev 41bff5fc54)"

# ---------- bundled data / IO ----------
def load_data(name):
    # dev mode: sibling data dir
    try:
        base = os.path.dirname(os.path.abspath(__file__))
        p = os.path.join(base, 'data', name)
        with open(p,'rb') as f: return f.read()
    except Exception:
        pass
    # zipapp mode: argv[0] is zip file
    try:
        import zipfile
        with zipfile.ZipFile(sys.argv[0]) as z:
            return z.read('data/'+name)
    except Exception:
        return b''

class BrokenOutput(Exception): pass

class Out:
    def __init__(self):
        self.buf = sys.stdout.buffer
        self.bytes_written = 0
    def write(self,b):
        if not b: return
        if isinstance(b,str): b=b.encode('utf-8','surrogateescape')
        try:
            self.buf.write(b); self.bytes_written += len(b)
        except BrokenPipeError:
            raise BrokenOutput()
        except OSError as e:
            if e.errno==errno.EPIPE: raise BrokenOutput()
            raise
    def flush(self):
        try: self.buf.flush()
        except (BrokenPipeError,OSError): raise BrokenOutput()

OUT = Out()
MESSAGES = True  # --no-messages flips this (module level for early errors)

def eprint_msg(b):
    if isinstance(b,str): b=b.encode('utf-8','surrogateescape')
    try: sys.stderr.buffer.write(b)
    except Exception: pass

def rg_error(msg, suppress=False):
    if suppress: return
    if isinstance(msg,str): msg=msg.encode('utf-8','surrogateescape')
    eprint_msg(b'rg: '+msg+(b'' if msg.endswith(b'\n') else b'\n'))

def os_error_str(e):
    # Rust std io error Display: "No such file or directory (os error 2)"
    msg = e.strerror or str(e)
    # Python uses "Is a directory", Rust same via strerror
    if e.errno is not None:
        return f"{msg} (os error {e.errno})"
    return msg

def fsb(s):
    return os.fsencode(s)

# ---------- sizes / numbers ----------
class FlagError(Exception):
    """message already full (without rg: prefix handled by caller printing)"""
    pass

def parse_u64(v, flag_disp):
    # Rust u64 parse: optional leading + , digits
    orig=v
    if v=='':
        raise FlagError(f"error parsing flag {flag_disp}: value is not a valid number: cannot parse integer from empty string")
    s=v[1:] if v.startswith('+') else v
    if s=='' or not all('0'<=c<='9' for c in s):
        raise FlagError(f"error parsing flag {flag_disp}: value is not a valid number: invalid digit found in string")
    try: n=int(s)
    except: n=0
    if n>18446744073709551615:
        raise FlagError(f"error parsing flag {flag_disp}: value is not a valid number: number too large to fit in target type")
    return n

def parse_size(v, flag_disp):
    # digits + optional K/M/G (upper only)
    mult=1; digits=v
    if v and v[-1] in 'KMG':
        mult={'K':1024,'M':1024**2,'G':1024**3}[v[-1]]; digits=v[:-1]
    if digits=='' or not all('0'<=c<='9' for c in digits):
        raise FlagError(f"error parsing flag {flag_disp}: invalid size: invalid format for size '{v}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix")
    n=int(digits)
    if n>18446744073709551615:
        raise FlagError(f"error parsing flag {flag_disp}: invalid size: invalid integer found in size '{v}': number too large to fit in target type")
    if n*mult>18446744073709551615:
        raise FlagError(f"error parsing flag {flag_disp}: invalid size: size too big in '{v}'")
    return n*mult

# ---------- glob ----------
class GlobError(Exception):
    def __init__(self,detail): super().__init__(detail); self.detail=detail

def _glob_expand_braces(pat):
    # returns list of expanded patterns; raises GlobError on unclosed '{'
    # find first unescaped { outside char class
    i=0; n=len(pat); in_class=False
    while i<n:
        c=pat[i]
        if c=='\\': i+=2; continue
        if c=='[': in_class=True
        elif c==']': in_class=False
        elif c=='{' and not in_class:
            # find matching }
            depth=1; j=i+1; commas=[]; incl=False
            while j<n:
                cj=pat[j]
                if cj=='\\': j+=2; continue
                if cj=='[': incl=True
                elif cj==']': incl=False
                elif not incl:
                    if cj=='{': depth+=1
                    elif cj=='}':
                        depth-=1
                        if depth==0: break
                    elif cj==',' and depth==1: commas.append(j)
                j+=1
            if j>=n:
                raise GlobError("unclosed alternate group; missing '}' (maybe escape '{' with '[{]'?)")
            if not commas:
                # Rust globset treats {x} as literal group? It just keeps x? Test: 'a{b}c' matched nothing on our files; globset treats as alternation of one -> abc. We'll expand.
                inner=pat[i+1:j]
                alts=[inner]
            else:
                alts=[]; prev=i+1
                for cm in commas: alts.append(pat[prev:cm]); prev=cm+1
                alts.append(pat[prev:j])
            out=[]
            for a in alts:
                out.extend(_glob_expand_braces(pat[:i]+a+pat[j+1:]))
            return out
        i+=1
    return [pat]

def _split_segments(pat):
    segs=[]; cur=''; i=0; in_class=False
    while i<len(pat):
        c=pat[i]
        if c=='\\' and i+1<len(pat): cur+=pat[i:i+2]; i+=2; continue
        if c=='[': in_class=True
        elif c==']': in_class=False
        if c=='/' and not in_class:
            segs.append(cur); cur=''
        else: cur+=c
        i+=1
    segs.append(cur)
    return segs

def _glob_class_regex(pat,i):
    # pat[i]=='['; returns (regex_str, next_index)
    n=len(pat); j=i+1; neg=False
    if j<n and pat[j] in '!^': neg=True; j+=1
    items=[]  # list of chars or (lo,hi)
    first=True
    # collect raw chars (handling range later)
    chars=[]  # elements: single char string (unescaped)
    closed=False
    while j<n:
        c=pat[j]
        if c==']' and not first:
            closed=True; j+=1; break
        first=False
        if c=='\\':
            if j+1>=n: raise GlobError("dangling '\\'")
            chars.append(pat[j+1]); j+=2; continue
        chars.append(c); j+=1
    if not closed:
        raise GlobError("unclosed character class; missing ']'")
    # interpret ranges: x-y where '-' not first/last
    out=[]; k=0
    while k<len(chars):
        if k+2<len(chars)+1 and k+2<=len(chars)-1 and chars[k+1]=='-' and k+2<len(chars):
            lo=chars[k]; hi=chars[k+2]
            if lo>hi:
                raise GlobError(f"invalid range; '{lo}' > '{hi}'")
            out.append(re.escape(lo)+'-'+re.escape(hi)); k+=3
        else:
            ch=chars[k]
            if ch in '\\[]^-': out.append('\\'+ch)
            else: out.append(re.escape(ch) if ch in '.+*?()|{}$' else ch)
            k+=1
    body=''.join(out)
    if neg: return '[^'+body+']', j
    return '['+body+']', j

def _glob_segment_regex(seg):
    out=[]; i=0; n=len(seg)
    while i<n:
        c=seg[i]
        if c=='*':
            while i<n and seg[i]=='*': i+=1
            out.append('[^/]*')
        elif c=='?': out.append('[^/]'); i+=1
        elif c=='[':
            r,i=_glob_class_regex(seg,i); out.append(r)
        elif c=='\\':
            if i+1>=n: raise GlobError("dangling '\\'")
            out.append(re.escape(seg[i+1])); i+=2
        else:
            out.append(re.escape(c)); i+=1
    return ''.join(out)

def glob_pattern_to_regex(pat):
    """Compile one gitwildmatch pattern (already brace-expanded? we expand here and combine)
    Returns regex string anchored ^...$ matching a full path string.
    The caller handles basename vs anchored by possibly prefixing pattern with **/ ."""
    exps=_glob_expand_braces(pat)
    parts=[]
    for e in exps:
        parts.append(_glob_one_regex(e))
    if len(parts)==1: return '^'+parts[0]+'$'
    return '^(?:'+ '|'.join(parts) +')$'

def _glob_one_regex(pat):
    # validate dangling backslash
    if pat.endswith('\\') and (len(pat)<2 or pat[-2]!='\\'):
        # odd number of trailing backslashes handled in segment parse too
        pass
    segs=_split_segments(pat)
    # leading slash -> first seg ''
    if segs and segs[0]=='': segs=segs[1:]
    if not segs: return ''
    out=[]; need_sep=False
    for idx,seg in enumerate(segs):
        last = idx==len(segs)-1
        first = idx==0
        if seg=='**':
            if first and last:
                out.append('.*'); need_sep=False
            elif first:
                out.append('(?:.*/)?'); need_sep=False
            elif last:
                out.append('(?:/.*)?' if need_sep else '.*'); need_sep=False
            else:
                out.append('/(?:.*/)?'); need_sep=False
        else:
            if need_sep: out.append('/')
            out.append(_glob_segment_regex(seg)); need_sep=True
    return ''.join(out)

class GlobMatcher:
    def __init__(self, pat, case_insensitive=False, basename=False):
        """basename=True: pattern matched against candidate basename-equivalent: we implement
        by requiring regex to match full candidate OR candidate after last '/'.
        If False, match full candidate."""
        self.pat=pat; self.basename=basename
        rx=glob_pattern_to_regex(pat)
        flags=re.IGNORECASE if case_insensitive else 0
        try: self.re=re.compile(rx,flags)
        except re.error as e: raise GlobError(str(e))
    def matches(self, cand):
        if self.re.match(cand): return True
        if self.basename and '/' in cand:
            return bool(self.re.match(cand.rsplit('/',1)[1]))
        return False

def compile_glob(pat, case_insensitive=False, basename=False):
    return GlobMatcher(pat, case_insensitive, basename)

# gitignore-style rule
class IgnoreRule:
    __slots__=('orig','whitelist','dir_only','matcher','anchored')
    def __init__(self, orig, whitelist, dir_only, matcher, anchored):
        self.orig=orig; self.whitelist=whitelist; self.dir_only=dir_only; self.matcher=matcher; self.anchored=anchored

def parse_ignore_pattern(line, case_insensitive=False):
    """line raw (without trailing newline). Returns IgnoreRule or None for blank/comment. Raises GlobError."""
    orig=line
    # leading \! \# escapes comment/negation detection later handled by strip rules
    # Check comment: first char '#'
    if line.startswith('#'): return None
    # strip trailing whitespace not escaped
    # count: trailing spaces where char before run isn't unescaped backslash
    # Simplify: process chars: we'll rstrip spaces that are not preceded by '\'
    s=line
    while s.endswith(' ') or s.endswith('\t'):
        # check if space escaped: number of backslashes before it is odd
        idx=len(s)-1; bs=0; k=idx-1
        while k>=0 and s[k]=='\\': bs+=1; k-=1
        if bs%2==1: break
        s=s[:-1]
    if s=='': return None
    # escaped trailing space: replace '\ ' with marker? glob escape handles '\ '
    whitelist=False; pat=s
    if pat.startswith('!'):
        whitelist=True; pat=pat[1:]
    elif pat.startswith('\\!') or pat.startswith('\\#'):
        pat=pat[1:]  # literal ! or # (escape removed, glob will treat as chars)
        # keep as literal char: prefix with backslash for glob escape of special? ! # not special in glob
    if pat=='': return None
    dir_only=False
    if pat.endswith('/') and not pat.endswith('\\/'):
        dir_only=True; pat=pat[:-1]
        if pat=='': return None
    anchored=False
    if pat.startswith('/'):
        anchored=True; pat=pat[1:]
    elif '/' in pat:
        anchored=True
    # '**/' patterns anchored flag fine
    matcher=compile_glob(pat, case_insensitive, basename=not anchored)
    return IgnoreRule(orig,whitelist,dir_only,matcher,anchored)

def ignore_rule_matches(rule, rel, is_dir):
    # rel: path relative to rule base, using '/'
    if rule.dir_only and not is_dir:
        # still matches if an ancestor dir matches; caller checks ancestors separately for files
        return False
    return rule.matcher.matches(rel)

