        while self.pos<self.n and self.pat[self.pos]=='|':
            self.pos+=1
            branches.append(self.parse_seq(flags.copy() if False else flags))
            # Note flag directives inside a branch mutate `flags` object shared; Rust flags
            # apply to rest of enclosing group (including later branches?) In regex crate,
            # (?i) in one branch applies from that point in the whole group, incl following
            # alternation branches textually. keep shared flags object.
        if len(branches)==1: return branches[0]
        return ('alt',branches)
    def parse_seq(self,flags):
        nodes=[]
        while True:
            self.skip_x(flags)
            if self.pos>=self.n: break
            c=self.pat[self.pos]
            if c=='|' or c==')': break
            # flag directive (?flags) must be intercepted
            if c=='(' and self._is_flag_directive():
                self._consume_flag_directive(flags)
                continue
            if c in '*+?':
                self.err(self.pos,1,'repetition operator missing expression')
            if c=='{':
                self.err(self.pos,1,'repetition operator missing expression')
            atom=self.parse_atom(flags)
            # repetitions
            while True:
                save=self.pos; self.skip_x(flags)
                if self.pos<self.n and self.pat[self.pos] in '*+?{':
                    atom=self.parse_repetition(atom,flags)
                else:
                    self.pos=save if False else self.pos
                    break
            nodes.append(atom)
        if not nodes: return ('empty',)
        if len(nodes)==1: return nodes[0]
        return ('seq',nodes)
    def _group_kind_peek(self):
        # at '('; return 'special' if ( ? X ) looks special
        if self.peek(1)!='?': return 'capture'
        third=self.peek(2)
        if third in ':P<=!' or third=='-' or (third.isalnum()):
            return 'special'
        return 'capture'
    def _is_flag_directive(self):
        # Determine if at (?...) with ) terminator (not colon) and special
        if self._group_kind_peek()!='special': return False
        third=self.peek(2)
        if third in ':P<': return False
        if third in '=!': return False
        # scan flags
        i=self.pos+2; seen_minus=False
        while i<self.n and self.pat[i] not in ':)':
            ch=self.pat[i]
            if ch=='-':
                if seen_minus: return False
                seen_minus=True; i+=1; continue
            if ch not in FLAG_CHARS:
                return False  # let parse_atom produce unrecognized flag error
            i+=1
        return i<self.n and self.pat[i]==')'
    def _consume_flag_directive(self,flags):
        # (?flags) or (?flags-flags)
        i=self.pos+2
        newf,_term,end=self._parse_flag_spec(i,flags)
        # mutate flags fields in place
        flags.i,flags.m,flags.s,flags.u,flags.x,flags.U,flags.R=newf.i,newf.m,newf.s,newf.u,newf.x,newf.U,newf.R
        self.pos=end+1  # skip ')'
    def _parse_flag_spec(self,i,base):
        # parse starting after (? ; returns (flags, terminator char ':' or ')', index of terminator)
        f=base.copy(); neg=False; start=i
        while i<self.n:
            ch=self.pat[i]
            if ch==':' or ch==')':
                if neg and False: pass
                return f,ch,i
            if ch=='-':
                if neg: self.err(i,1,'unrecognized flag')
                # check dangling: next is ) or :
                if i+1<self.n and self.pat[i+1] in ':)':
                    self.err(i,1,'dangling flag negation operator')
                neg=True; i+=1; continue
            if ch not in FLAG_CHARS:
                self.err(i,1,'unrecognized flag')
            val=not neg
            if ch=='i': f.i=val
            elif ch=='m': f.m=val
            elif ch=='s': f.s=val
            elif ch=='u': f.u=val
            elif ch=='x': f.x=val
            elif ch=='U': f.U=val
            elif ch=='R': f.R=val
            i+=1
        # EOF while in flag spec (shouldn't happen for wrapped pattern except top-level effective always closes)
        self.err(start,1,'unrecognized flag')
    def parse_repetition(self,atom,flags):
        start=self.pos; c=self.pat[self.pos]
        if c=='*': mn,mx=0,None; self.pos+=1
        elif c=='+': mn,mx=1,None; self.pos+=1
        elif c=='?': mn,mx=0,1; self.pos+=1
        elif c=='{':
            mn,mx=self._parse_counted()
        else: return atom
        lazy=False
        if self.pos<self.n and self.pat[self.pos]=='?':
            lazy=True; self.pos+=1
        if flags.U: lazy=not lazy
        return ('rep',atom,mn,mx,lazy)
    def _parse_counted(self):
        # at '{'
        brace=self.pos; self.pos+=1
        dstart=self.pos
        if self.pos>=self.n or not self.pat[self.pos].isdigit():
            self.err(self.pos if self.pos<self.n else dstart,1,'repetition quantifier expects a valid decimal')
        s1=''
        while self.pos<self.n and self.pat[self.pos].isdigit(): s1+=self.pat[self.pos]; self.pos+=1
        if len(s1)>10 or int(s1)>4294967295:
            self.err(dstart,len(s1),'decimal literal invalid')
        mn=int(s1); mx=mn
        if self.pos<self.n and self.pat[self.pos]==',':
            self.pos+=1; s2=''
            while self.pos<self.n and self.pat[self.pos].isdigit(): s2+=self.pat[self.pos]; self.pos+=1
            if s2=='':
                mx=None
            else:
                if len(s2)>10 or int(s2)>4294967295: self.err(self.pos-len(s2),len(s2),'decimal literal invalid')
                mx=int(s2)
        if self.pos>=self.n or self.pat[self.pos]!='}':
            # span from first digit to end
            self.err(dstart, max(1,self.n-dstart),'unclosed counted repetition')
        self.pos+=1
        if mx is not None and mx<mn:
            self.err(brace,(self.pos-1)-brace+1,'invalid repetition count range, the start must be <= the end')
        return mn,mx
    def parse_atom(self,flags):
        c=self.pat[self.pos]
        if c=='(':
            return self.parse_group(flags)
        if c=='[':
            cls=self.parse_class(flags)
            return ('class',cls,flags.copy())
        if c=='.': self.pos+=1; return ('dot',flags.copy())
        if c=='^': self.pos+=1; return ('anchor','^',flags.copy())
        if c=='$': self.pos+=1; return ('anchor','$',flags.copy())
        if c=='\\':
            return self.parse_escape(flags,in_class=False)
        # literal char (includes ']', '}', etc.)
        self.pos+=1
        return ('lit',c,flags.copy())
    def parse_group(self,flags):
        start=self.pos; self.pos+=1
        kind='cap'; name=None
        inner_flags=flags.copy()
        if self.pos<self.n and self.pat[self.pos]=='?' and self._group_kind_peek()=='special':
            third=self.peek(1)  # char after '?'
            if third==':':
                kind='noncap'; self.pos+=2
            elif third=='=' or third=='!':
                self.err(start,3,'look-around, including look-ahead and look-behind, is not supported')
            elif third=='P':
                # (?P<name>...)
                if self.peek(2)!='<':
                    self.err(self.pos+1,1,'unrecognized flag')  # at P
                name=self._parse_capture_name(self.pos+2)  # index of '<'
                kind='cap'
            elif third=='<':
                nxt=self.peek(2)
                if nxt in '=!':
                    self.err(start,4,'look-around, including look-ahead and look-behind, is not supported')
                name=self._parse_capture_name(self.pos+1)
                kind='cap'
            else:
                # flags, scoped (?flags:...)
                f,term,end=self._parse_flag_spec(self.pos+1,flags)
                if term==')':
                    # This is a flag directive which parse_seq should have intercepted;
                    # if reached (e.g after atom?), treat as empty with flags side effect impossible here.
                    self.pos=end+1
                    return ('empty',)
                inner_flags=f; kind='noncap'; self.pos=end+1
        # register capture before parsing inner (numbering by opening)
        capidx=0; pyname=None
        if kind=='cap':
            self.cap_counter+=1; capidx=self.cap_counter
            if name is not None:
                if name in self.name_to_index:
                    # duplicate: span both groups approx: report at first 'pattern' positions - we use start
                    # Rust reports two spans; our single-span error uses this group start
                    self.err(start,3,'duplicate capture group name')
                pyname=f'_rg{capidx}'
                self.name_to_index[name]=(capidx,pyname,start)
        node=self.parse_alt(inner_flags)
        if self.pos>=self.n or self.pat[self.pos]!=')':
            self.err(start,1,'unclosed group')
        self.pos+=1
        return ('group',node,capidx,(name,pyname))
    def _parse_capture_name(self,lt_index):
        # lt_index points at '<' in self.pat coordinates relative to parser pos? We passed absolute index
        # Actually _parse_capture_name receives absolute index of '<'
        i=lt_index+1
        if i<self.n and self.pat[i]=='>':
            self.err(i,1,'empty capture group name')
        name=''
        first=True
        while i<self.n:
            ch=self.pat[i]
            if ch=='>':
                if not name: self.err(i,1,'empty capture group name')
                self.pos=i+1
                return name
            ok = ch.isalpha() or ch=='_' if first else (ch.isalnum() or ch in '_.[]')
            # Rust allows [A-Za-z0-9_.[\]] but first must not be digit; allow unicode alpha like rust? capture names may be ASCII only in regex crate (it allows alphabetic unicode?)
            if not ok:
                self.err(i,1,'invalid capture group character')
            name+=ch; first=False; i+=1
        self.err(i if i<self.n else lt_index,1,'invalid capture group character')
    def parse_escape(self,flags,in_class=False):
        start=self.pos; self.pos+=1
        if self.pos>=self.n:
            self.err(start,1,'unclosed group')  # unreachable for wrapped
        c=self.pat[self.pos]; self.pos+=1
        if c.isdigit():
            self.err(start,2,'backreferences are not supported')
        simple={'a':'\x07','f':'\x0c','t':'\t','n':'\n','r':'\r','v':'\x0b'}
        if c in simple:
            if in_class: return ClassItem('char',simple[c])
            return ('lit',simple[c],flags.copy())
        if c=='x' or c=='u' or c=='U':
            ch=self._parse_hex(c,start)
            if in_class: return ClassItem('char',ch)
            return ('lit',ch,flags.copy())
        if c in 'dDsSwW':
            if in_class: return ClassItem('perl',c)
            return ('perl',c,flags.copy())
        if c=='p' or c=='P':
            prop=self._parse_unicode_prop(c,start)
            if in_class: return prop
            return ('class',_prop_to_class(prop,c=='P'),flags.copy())
        if c=='b':
            if in_class: self.err(start,2,'invalid escape sequence found in character class')
            # \b{...} special if next is '{' and content starts with alpha
            if self.pos<self.n and self.pat[self.pos]=='{' and self.pos+1<self.n and self.pat[self.pos+1].isalpha():
                bstart=self.pos; j=self.pos+1; name=''
                while j<self.n and (self.pat[j].isalpha() or self.pat[j]=='-'):
                    name+=self.pat[j]; j+=1
                if j>=self.n or self.pat[j]!='}':
                    self.err(bstart, j-bstart if j>bstart else 1,'special word boundary assertion is either unclosed or contains an invalid character')
                if name not in ('start','end','start-half','end-half'):
                    self.err(bstart+1,len(name),'unrecognized special word boundary assertion, valid choices are: start, end, start-half or end-half')
                self.pos=j+1
                return ('anchor','b'+name,flags.copy())
            return ('anchor','b',flags.copy())
        if c=='B':
            if in_class: self.err(start,2,'invalid escape sequence found in character class')
            return ('anchor','B',flags.copy())
        if c=='A':
            if in_class: self.err(start,2,'invalid escape sequence found in character class')
            return ('anchor','A',flags.copy())
        if c=='z':
            if in_class: self.err(start,2,'invalid escape sequence found in character class')
            return ('anchor','z',flags.copy())
        if c.isalnum():
            self.err(start,2,'unrecognized escape sequence')
        # punctuation / space -> literal
        if in_class: return ClassItem('char',c)
        return ('lit',c,flags.copy())
    def _parse_hex(self,kind,start):
        # kind x (2 or braces), u (4 or braces), U (8 or braces)
        if self.pos<self.n and self.pat[self.pos]=='{':
            self.pos+=1; hs=self.pos; hexs=''
            while self.pos<self.n and self.pat[self.pos]!='}':
                ch=self.pat[self.pos]
                if ch not in '0123456789abcdefABCDEF':
                    self.err(self.pos,1,'invalid hexadecimal digit')
                hexs+=ch; self.pos+=1
            if self.pos>=self.n:
                self.err(hs,1,'invalid hexadecimal digit')
            if hexs=='':
                # span: braces content position - Rust points at '{}' (2 chars)
                self.err(hs-1,2,'hexadecimal literal empty')
            self.pos+=1
            val=int(hexs,16) if len(hexs)<=8 else 0x110000
            if not _is_scalar(val):
                self.err(hs,len(hexs),'hexadecimal literal is not a Unicode scalar value')
            return chr(val)
        need={'x':2,'u':4,'U':8}[kind]; hs=self.pos; hexs=''
        for _ in range(need):
            if self.pos>=self.n or self.pat[self.pos] not in '0123456789abcdefABCDEF':
                self.err(self.pos if self.pos<self.n else hs,1,'invalid hexadecimal digit')
            hexs+=self.pat[self.pos]; self.pos+=1
        val=int(hexs,16)
        if not _is_scalar(val):
            self.err(hs,len(hexs),'hexadecimal literal is not a Unicode scalar value')
        return chr(val)
    def _parse_unicode_prop(self,kindchar,start):
        # returns ClassItem('prop', name_str) ; negation for \P handled by caller in_class item kind 'propneg'
        if self.pos<self.n and self.pat[self.pos]=='{':
            self.pos+=1; ns=self.pos; name=''
            while self.pos<self.n and self.pat[self.pos]!='}':
                name+=self.pat[self.pos]; self.pos+=1
            if self.pos>=self.n:
                self.err(self.pos,1,'incomplete escape sequence, reached end of pattern prematurely')
            self.pos+=1
            # validate now
            _validate_unicode_prop(name,start,self.pos-start,self)
            return ClassItem('prop' if kindchar=='p' else 'propneg',name)
        else:
            if self.pos>=self.n:
                self.err(self.pos,1,'incomplete escape sequence, reached end of pattern prematurely')
            c=self.pat[self.pos]; self.pos+=1
            _validate_unicode_prop(c,start,3,self)
            return ClassItem('prop' if kindchar=='p' else 'propneg',c)
    def parse_class(self,flags):
        start=self.pos; self.pos+=1
        neg=False
        if self.pos<self.n and self.pat[self.pos]=='^': neg=True; self.pos+=1
        items=[]; first=True
        # Parse items until ']' (first ] literal)
        # We'll parse element-wise, handling ranges and && / -- operators.
        # elements: ClassItem or ('op',opstr)
        prev_literal=None  # index in items of last char item
        while True:
            if self.pos>=self.n:
                self.err(start,1,'unclosed character class')
            c=self.pat[self.pos]
            if c==']' and not first:
                self.pos+=1; break
            first=False
            # set operators && and --
            if c=='&' and self.peek(1)=='&' and items:
                items.append(ClassItem('op','&&')); self.pos+=2; first=True; prev_literal=None; continue
            # POSIX [:alpha:] / [:^alpha:]
            if c=='[' and self.peek(1)==':':
                end=self.pat.find(':]',self.pos+2)
                if end!=-1:
                    inner=self.pat[self.pos+2:end]; pneg=False
                    if inner.startswith('^'): pneg=True; inner=inner[1:]
                    if inner in PERL_POSIX:
                        items.append(ClassItem('posixneg' if pneg else 'posix',inner)); self.pos=end+2; prev_literal=None; continue
                    # unknown posix: Rust error? Treat as nested class chars fallthrough
            # range handling if next char is '-' and following isn't ']' and prev is literal char
            # We parse an element first
            elem_start=self.pos
            if c=='[':
                # nested class
                sub=self.parse_class(flags)
                elem=ClassItem('class',sub)
            elif c=='\\':
                elem=self.parse_escape(flags,in_class=True)
            elif c=='-' and items and prev_literal is not None:
                # handled below as range separator - shouldn't reach as element
                elem=ClassItem('char','-'); self.pos+=1
            else:
                elem=ClassItem('char',c); self.pos+=1
            # check range: '-' not followed by ']' (and not '--' op) and elem is char
            if elem.kind=='char' and self.pos<self.n and self.pat[self.pos]=='-' and not (self.peek(1)=='-' ) and self.peek(1)!=']' and self.peek(1)!='':
                # peek(1) is char after '-' ; if it's class escape \d etc -> error invalid range boundary
                after=self.pos+1
                if after<self.n and self.pat[after]=='\\':
                    # parse following element to see if char literal
                    save=self.pos
                    self.pos+=1
                    nxt_start=self.pos
                    nxt=self.parse_escape(flags,in_class=True)
                    if nxt.kind!='char':
                        self.err(nxt_start,2,'invalid range boundary, must be a literal')
                    hi=nxt.a
                elif after<self.n and self.pat[after]=='[':
                    self.err(after,1,'invalid range boundary, must be a literal')
                else:
                    self.pos+=1
                    if self.pos>=self.n: self.err(start,1,'unclosed character class')
                    hi=self.pat[self.pos]; self.pos+=1
                lo=elem.a
                if lo>hi:
                    self.err(elem_start,(self.pos-elem_start),'invalid character class range, the start must be <= the end')
                items.append(ClassItem('range',lo,hi)); prev_literal=None; continue
            if elem.kind=='perl' or elem.kind=='prop' or elem.kind=='propneg':
                # if followed by '-' + non-] -> invalid range boundary at this escape
                if self.pos<self.n and self.pat[self.pos]=='-' and self.peek(1)!=']' and self.peek(1)!='-' and self.peek(1)!='':
                    self.err(elem_start,2,'invalid range boundary, must be a literal')
            items.append(elem)
            prev_literal=len(items)-1 if elem.kind=='char' else None
        return CharClass(neg,items,start)

def _prop_to_class(item, neg):
    return CharClass(neg or item.kind=='propneg',[ClassItem('prop',item.a)],0)

# Unicode property validation/resolution
_CAT_FULL={'letter':'L','uppercaseletter':'Lu','lowercaseletter':'Ll','titlecaseletter':'Lt','modifierletter':'Lm','otherletter':'Lo',
 'mark':'M','nonspacingmark':'Mn','spacingmark':'Mc','enclosingmark':'Me',
 'number':'N','decimalnumber':'Nd','letternumber':'Nl','othernumber':'No',
 'punctuation':'P','connectorpunctuation':'Pc','dashpunctuation':'Pd','openpunctuation':'Ps','closepunctuation':'Pe','initialpunctuation':'Pi','finalpunctuation':'Pf','otherpunctuation':'Po',
 'symbol':'S','mathsymbol':'Sm','currencysymbol':'Sc','modifiersymbol':'Sk','othersymbol':'So',
 'separator':'Z','spaceseparator':'Zs','lineseparator':'Zl','paragraphseparator':'Zp',
 'other':'C','control':'Cc','format':'Cf','surrogate':'Cs','privateuse':'Co','unassigned':'Cn','cntrl':'Cc'}
_CAT_ABBR=set(['L','Lu','Ll','Lt','Lm','Lo','M','Mn','Mc','Me','N','Nd','Nl','No','P','Pc','Pd','Ps','Pe','Pi','Pf','Po','S','Sm','Sc','Sk','So','Z','Zs','Zl','Zp','C','Cc','Cf','Cs','Co','Cn'])
_SCRIPT_ALIASES={'grek':'Greek','latn':'Latin','cyrl':'Cyrillic','hani':'Han','hira':'Hiragana','kana':'Katakana','hang':'Hangul','hebr':'Hebrew','arab':'Arabic','armn':'Armenian','geor':'Georgian','deva':'Devanagari','beng':'Bengali','thai':'Thai','laoo':'Lao','ethi':'Ethiopic','taml':'Tamil','telu':'Telugu','knda':'Kannada','mlym':'Malayalam','gujr':'Gujarati','guru':'Gurmukhi','orya':'Oriya','sinh':'Sinhala','mymr':'Myanmar','khmr':'Khmer','mong':'Mongolian','tibt':'Tibetan','cher':'Cherokee','cans':'CanadianAboriginal','syrc':'Syriac','thaa':'Thaana','nkoo':'Nko','common':'Common','inherited':'Inherited'}
def _norm_prop(s): return ''.join(ch for ch in s.lower() if ch not in ' _-')

def _validate_unicode_prop(name, span_start, span_len, parser):
    # raises parser.err if unknown
    try:
        resolve_unicode_prop(name)
    except KeyError as e:
        kind=str(e.args[0]) if e.args else 'prop'
        if kind=='value':
            parser.err(span_start,span_len,'Unicode property value not found')
        else:
            parser.err(span_start,span_len,'Unicode property not found')

_prop_cache={}
def resolve_unicode_prop(name):
    """Return list of (lo,hi) codepoint ranges. Raise KeyError('prop'|'value')."""
    if name in _prop_cache: return _prop_cache[name]
    ranges=_resolve_unicode_prop_uncached(name)
    _prop_cache[name]=ranges
    return ranges

def _ranges_from_predicate(pred):
    ranges=[]; start=None; prev=None
    for cp in range(0x110000):
        if 0xD800<=cp<=0xDFFF:
            if start is not None: ranges.append((start,prev)); start=None
            continue
        if pred(cp):
            if start is None: start=cp
            prev=cp
        else:
            if start is not None: ranges.append((start,prev)); start=None
    if start is not None: ranges.append((start,prev))
    return ranges

def _resolve_unicode_prop_uncached(name):
    raw=name
    if '=' in name:
        k,v=name.split('=',1); nk=_norm_prop(k); nv=_norm_prop(v)
        if nk in ('gc','generalcategory','generacategory','category'):
            # value may be abbreviation as-is case-sensitive-ish or full name normalized
            code=None
            if v in _CAT_ABBR: code=v
            elif nv in _CAT_FULL: code=_CAT_FULL[nv]
            elif len(v)==1 and v.upper() in _CAT_ABBR: code=v.upper()
            if code is None: raise KeyError('value')
            return _cat_ranges(code)
        if nk in ('sc','script','scx','scriptextension','scriptextensions'):
            r=_script_ranges(v)
            if r is None: raise KeyError('value')
            return r
        if nk in ('age','blk','block'):
            raise KeyError('value')
        raise KeyError('prop')
    nn=_norm_prop(name)
    if len(name)==1 or name in _CAT_ABBR or nn in _CAT_FULL:
        code=name if name in _CAT_ABBR else _CAT_FULL.get(nn)
        if code is None and len(name)==1 and name.isupper(): code=name
        if code and (code in _CAT_ABBR): return _cat_ranges(code)
    if nn in ('any',): return [(0,0x10FFFF)]
    if nn in ('ascii',): return [(0,0x7F)]
    if nn in ('assigned','assigned'): return _cat_ranges_excluding('Cn')
    if nn in ('alpha','alphabetic'):
        return _ranges_from_predicate(lambda cp: chr(cp).isalpha() or unicodedata.category(chr(cp))=='Nl')
    if nn in ('uppercase',): return _ranges_from_predicate(lambda cp: chr(cp).isupper())
    if nn in ('lowercase',): return _ranges_from_predicate(lambda cp: chr(cp).islower())
    if nn in ('whitespace',):
        ws=[0x9,0xA,0xB,0xC,0xD,0x20,0x85,0xA0,0x1680,0x2000,0x2001,0x2002,0x2003,0x2004,0x2005,0x2006,0x2007,0x2008,0x2009,0x200A,0x2028,0x2029,0x202F,0x205F,0x3000]
        return [(c,c) for c in ws]
    # script by name
    r=_script_ranges(name)
    if r is not None: return r
    raise KeyError('prop')

def _cat_ranges(code):
    if len(code)==1:
        return _ranges_from_predicate(lambda cp: unicodedata.category(chr(cp)).startswith(code))
    return _ranges_from_predicate(lambda cp: unicodedata.category(chr(cp))==code)
def _cat_ranges_excluding(code):
    return _ranges_from_predicate(lambda cp: unicodedata.category(chr(cp))!=code)

_script_cache=None
def _script_ranges(v):
    global _script_cache
