class RegexParseError(Exception):
    def __init__(self, span_start, span_len, msg):
        super().__init__(msg); self.start=span_start; self.len=max(1,span_len); self.msg=msg

@dataclass
class ReFlags:
    i: bool=False; m: bool=True; s: bool=False; u: bool=True; x: bool=False; U: bool=False; R: bool=False
    def copy(self): return ReFlags(self.i,self.m,self.s,self.u,self.x,self.U,self.R)

