# ('empty',) ('lit',ch,flags) ('dot',flags) ('class',ClassObj,flags) ('perl',kind,flags) kind d D s S w W
# ('anchor',kind,flags) kind ^ $ A z b B bstart bend bstart_half bend_half
# ('seq',[nodes]) ('alt',[nodes]) ('rep',node,min,max,lazy) ('group',node,capindex_or_0,name_or_None)

@dataclass
class ClassItem:
    kind: str  # 'char','range','perl','posix','prop','class'
    a: object=None; b: object=None

@dataclass
class CharClass:
    negated: bool
    items: list  # ClassItem plus ('op','&&') handled via expr below
    # for set operations we store expr tree instead when needed: ('set', CharClass) / ('and',[...]) etc in items as ClassItem('expr',tree)
    span: int=0

