class RegexBuildError(Exception): pass

def format_regex_error(effective,e):
    # Rust regex crate error display with multi-line patterns: simplify to single-line rendering if no newline in pattern
    pat=effective
    if '\n' in pat:
        # crate prints with line numbers etc; approximate by showing pattern raw
        return f"regex parse error:\n    {pat}\nerror: {e.msg}"
    caret=' '*(4+e.start)+'^'*max(1,e.len)
