def rust_regex_escape(s):
    # escape for fixed strings: escape regex meta and whitespace/control as regex crate escape does
    out=[]
    for ch in s:
        if ch in '\\.[]{}()+-*?^$|#':
            out.append('\\'+ch)
        elif ch=='\n': out.append('\\n')
