# ----- char set ranges utilities -----
def _norm_ranges(rs):
    rs=sorted([(a,b) for a,b in rs if a<=b])
    out=[]
    for a,b in rs:
        if out and a<=out[-1][1]+1: out[-1]=(out[-1][0],max(out[-1][1],b))
        else: out.append((a,b))
    return out
def _invert_ranges(rs,universe):
    rs=_norm_ranges(rs); out=[]
    for ua,ub in universe:
        cur=ua
        for a,b in rs:
            if b<cur or a>ub: continue
            if a>cur: out.append((cur,min(a-1,ub)))
            cur=max(cur,b+1)
            if cur>ub: break
        if cur<=ub: out.append((cur,ub))
    return _norm_ranges(out)
