class StdinStore:
    def __init__(self): self.consumed=False; self.data=None
    def read(self):
        if self.consumed: return b''
        self.consumed=True
        try: return sys.stdin.buffer.read()
        except Exception: return b''
STDIN_STORE=StdinStore()

@dataclass
class PreparedData:
    data: bytes
    binary_offset: object=None
    reader_convert: bool=False
    mmap_like: bool=False
    error: bool=False
    skip: bool=False

def transcode_data(raw, encoding):
    if encoding=='none': return raw
    if encoding is None:
        if raw.startswith(codecs.BOM_UTF8):
            return raw[len(codecs.BOM_UTF8):].decode('utf-8','surrogateescape').encode('utf-8','surrogateescape')
        if raw.startswith(codecs.BOM_UTF16_LE):
            return raw.decode('utf-16le','replace').lstrip('\ufeff').encode('utf-8')
        if raw.startswith(codecs.BOM_UTF16_BE):
            return raw.decode('utf-16be','replace').lstrip('\ufeff').encode('utf-8')
        return raw
    if encoding=='x-user-defined':
        s=''.join(chr(b) if b<128 else chr(0xF700+b) for b in raw)
        return s.encode('utf-8')
    try:
        s=raw.decode(encoding,'replace')
    except Exception:
        s=raw.decode('utf-8','replace')
    if s.startswith('\ufeff'): s=s[1:]
    return s.encode('utf-8')

def _fmt_cmd_for_error(cmd,path):
    return f'"{cmd}" "{path}"'

def prepare_source(src,pa,pre_globs):
    o=pa.o
    # stdin
    if src.is_stdin:
        raw=STDIN_STORE.read()
        data=transcode_data(raw,o['encoding'])
        return PreparedData(data,None,False,False)
    path=src.path
    # determine pre vs zip
    use_pre=False; use_zip=False; zip_kind=None
    if o['pre'] is not None and o['search_zip']:
        # last flag wins recorded in opts (set below in build hiargs if absent default pre)
        last=o.get('_pre_zip_last','pre')
        use_pre=(last=='pre'); use_zip=(last=='zip')
    elif o['pre'] is not None: use_pre=True
    elif o['search_zip']: use_zip=True
    if use_zip:
        ext=os.path.splitext(path)[1].lower() if '.' in os.path.basename(path) else ''
        # original extension case: .Z is uppercase significant, lower mapping handles .gz etc; check exact .Z before lower
        if path.endswith('.Z'): zip_kind='gzip'
        elif ext in ZIP_EXTS: zip_kind=ZIP_EXTS[ext]
        if zip_kind is None: use_zip=False
