        # last flag wins recorded in opts (set below in build hiargs if absent default pre)
        last=o.get('_pre_zip_last','pre')
        use_pre=(last=='pre'); use_zip=(last=='zip')
    elif o['pre'] is not None: use_pre=True
    elif o['search_zip']: use_zip=True
    if use_zip:
        ext=os.path.splitext(path)[1].lower() if '.' in os.path.basename(path) else ''
        # original extension case: .Z is uppercase significant, lower mapping handles .gz etc; check exact .Z before lower
        if path.endswith('.Z'): zip_kind='gzip'
        elif ext in ZIP_EXTS: zip_kind=ZIP_EXTS[ext]
        if zip_kind is None: use_zip=False
    if use_pre and pre_globs is not None:
        abs_path=os.path.abspath(path)
        if not pre_globs.matches(abs_path,src.display): use_pre=False
    data=None; had_error=False
    if use_pre:
        cmd=o['pre']
        try:
            fh=open(path,'rb')
        except OSError as e:
            # handled as read error by caller via exception
            raise
        try:
            proc=subprocess.Popen([cmd,path],stdin=fh,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        except OSError as e:
            fh.close()
            msg=f"{src.out_path()}: preprocessor command could not start: '{_fmt_cmd_for_error(cmd,path)}': {os_error_str(e)}"
            if o['messages']: rg_error(msg.encode('utf-8','surrogateescape'))
            return PreparedData(b'',error=True)
        out,err=proc.communicate(); fh.close()
        data=out
        if proc.returncode!=0:
            had_error=True
            if o['messages']:
                errtxt=err.decode('utf-8','surrogateescape')
                sep='-'*79
                msg=f"{src.out_path()}: preprocessor command failed: '{_fmt_cmd_for_error(cmd,path)}': \n{sep}\n{errtxt}{'' if errtxt.endswith(chr(10)) or errtxt=='' else chr(10)}{sep}"
                rg_error(msg.encode('utf-8','surrogateescape'))
    elif use_zip:
        cmd=ZIP_CMDS[zip_kind]
        try:
            proc=subprocess.Popen(cmd+[path],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        except OSError:
            return PreparedData(b'',skip=True)
        out,err=proc.communicate(); data=out
        if proc.returncode!=0:
            had_error=True
            if o['messages']:
                errtxt=err.decode('utf-8','surrogateescape')
                sep='-'*79
                msg=f"{src.out_path()}: \n{sep}\n{errtxt}{'' if errtxt.endswith(chr(10)) or errtxt=='' else chr(10)}{sep}"
                rg_error(msg.encode('utf-8','surrogateescape'))
    else:
        with open(path,'rb') as fh: data=fh.read()
    data=transcode_data(data,o['encoding'])
    # mmap_like determination
    mmap_like=False
    if o['mmap'] and src.explicit and not use_pre and not use_zip:
        try:
            if os.path.isfile(path): mmap_like=True
        except Exception: pass
    return PreparedData(data,None,False,mmap_like,error=had_error)

