@dataclass
class LineInfo:
    raw: bytes       # including terminator
    start: int       # byte offset in data
    text: str        # full incl terminator decoded internal
    content: str     # without terminator
    content_bytes: bytes
    char_start: int=0
@dataclass
class SubMatch:
    start_byte_block: int; end_byte_block: int; text_bytes: bytes; match: object
    start_byte_line: int=0; abs_byte: int=0; line_idx: int=0
@dataclass
class MatchBlock:
    line_indices: list
    subs: list
@dataclass
class FileResult:
    src: object; lines: list; blocks: list
    matched_lines: int=0; matches: int=0; bytes_searched: int=0
    binary_offset: object=None; binary_mode: str='text'; suppressed: bool=False
    searched_line_count: int=0; text: str=''; data_len: int=0; elapsed: float=0.0
    count_value: int=0; true_multiline: bool=False; error: bool=False

def decode_internal(data,model):
    return data.decode('latin1') if model=='bytes' else data.decode('utf-8','surrogateescape')
def encode_internal(text,model):
    return text.encode('latin1') if model=='bytes' else text.encode('utf-8','surrogateescape')
def byte_len_of(text,model): return len(encode_internal(text,model))

def split_lines(data,term,model):
    lines=[]; pos=0; char_pos=0
    while pos<len(data):
        idx=data.find(term,pos)
        if idx==-1:
            chunk=data[pos:]; nextpos=len(data); has_term=False
        else:
            chunk=data[pos:idx+len(term)]; nextpos=idx+len(term); has_term=True
        text=decode_internal(chunk,model)
        content_bytes=chunk[:-len(term)] if has_term else chunk
        content=decode_internal(content_bytes,model)
        lines.append(LineInfo(chunk,pos,text,content,content_bytes,char_pos))
        char_pos+=len(text); pos=nextpos
    return lines

def search_source(src,matcher,pa,pre_globs):
    o=pa.o; t0=time.time()
    try:
        prep=prepare_source(src,pa,pre_globs)
    except OSError as e:
        # read error
        msg=f"{src.out_path()}: {os_error_str(e)}"
        if o['messages']: rg_error(msg.encode('utf-8','surrogateescape'))
        return FileResult(src,[],[],error=True)
    if prep.skip:
        r=FileResult(src,[],[]); r.error=False; r.suppressed=True; r.bytes_searched=0; return r
    data=prep.data
    # binary mode classification
    if o['null_data'] or o['text']: bmode='text'
    elif o['binary']: bmode='binary'
    elif src.explicit or src.is_stdin: bmode='binary'
    else: bmode='quit'
    first_nul=data.find(b'\x00') if (bmode!='text' and not o['null_data']) else -1
    binary_offset=first_nul if first_nul>=0 else None
    if bmode=='quit' and binary_offset is not None:
        r=FileResult(src,[],[]); r.suppressed=True; r.binary_offset=binary_offset; r.binary_mode='quit'
        r.bytes_searched=0; r.data_len=len(data); r.elapsed=time.time()-t0; r.error=prep.error
        return r
    reader_convert=False
    if bmode=='binary' and binary_offset is not None and not prep.mmap_like:
        reader_convert=True
        data=data.replace(b'\x00',b'\n')
    model=matcher.model if matcher else ('bytes' if o['no_unicode'] else 'unicode')
    term=b'\x00' if o['null_data'] else b'\n'
    lines=split_lines(data,term,model)
    text_all=decode_internal(data,model)
    result=FileResult(src,lines,[])
    result.binary_offset=binary_offset if bmode=='binary' else None
    result.binary_mode=bmode; result.data_len=len(data); result.text=text_all
    result.searched_line_count=len(lines); result.error=prep.error
    if matcher is None:
        result.bytes_searched=len(data); result.elapsed=time.time()-t0; return result
    max_count=o['max_count']
    invert=o['invert_match']
    true_multi=bool(o['multiline'] and matcher.can_match_newline())
    result.true_multiline=true_multi
    blocks=[]
    # multiline dotall: handled at matcher build initial flags below (patched via opts in matcher creation)
    if true_multi and not invert:
        # whole-text search
        raw_matches=list(matcher.find_iter(text_all,'multi'))
        # map matches to expanded line blocks and merge adjacent
        line_starts=[ln.char_start for ln in lines]
        import bisect
        def line_of(pos,end=False):
            if not lines: return 0
            if end and pos>0: pos=pos-1
            idx=bisect.bisect_right(line_starts,pos)-1
            return max(0,min(idx,len(lines)-1))
        tmp=[]  # (l0,l1,sub raw match)
        for m in raw_matches:
            if not lines: continue
            l0=line_of(m.start()); l1=line_of(m.end(),end=True) if m.end()>m.start() else line_of(m.start())
            tmp.append([l0,l1,[m]])
        merged=[]
        for item in tmp:
            if merged and item[0]<=merged[-1][1]+1:
                merged[-1][1]=max(merged[-1][1],item[1]); merged[-1][2].extend(item[2])
            else: merged.append(item)
        # stop-on-nonmatch: keep blocks until first gap after first block
        if o['stop_on_nonmatch'] and merged:
            kept=[merged[0]]
            # if next block is non-contiguous (gap >=1 line), stop at first gap line
            if len(merged)>1 and merged[1][0]>merged[0][1]+1:
                gap_idx=merged[0][1]+1
                result.searched_line_count=gap_idx+1
            merged=kept if (len(merged)>1 and merged[1][0]>merged[0][1]+1) else merged
            if result.searched_line_count and result.searched_line_count<len(lines):
                merged=kept
        if max_count is not None: merged=merged[:max_count]
        for l0,l1,ms in merged:
            block_start_byte=lines[l0].start
            subs=[]
            for m in ms:
                sb=byte_len_of(text_all[:m.start()],model)
                eb=byte_len_of(text_all[:m.end()],model)
                li=line_of(m.start())
                subs.append(SubMatch(sb-block_start_byte,eb-block_start_byte,encode_internal(m.group(0),model),m,sb-lines[li].start,sb,li))
            blocks.append(MatchBlock(list(range(l0,l1+1)),subs))
    elif true_multi and invert:
        raw_matches=list(matcher.find_iter(text_all,'multi'))
        line_starts=[ln.char_start for ln in lines]
        import bisect
        def line_of(pos,end=False):
            if not lines: return 0
            if end and pos>0: pos=pos-1
            idx=bisect.bisect_right(line_starts,pos)-1
            return max(0,min(idx,len(lines)-1))
        matched=set()
        for m in raw_matches:
            l0=line_of(m.start()); l1=line_of(m.end(),end=True) if m.end()>m.start() else line_of(m.start())
            for k in range(l0,l1+1): matched.add(k)
        for idx in range(len(lines)):
            if idx not in matched:
                if max_count is not None and len(blocks)>=max_count: break
                blocks.append(MatchBlock([idx],[]))
    else:
        # line-by-line
        had_block=False
        for idx,ln in enumerate(lines):
            if max_count is not None and len(blocks)>=max_count: break
            ms=list(matcher.find_iter(ln.content,'line'))
            is_match=bool(ms)
            emit=(not is_match) if invert else is_match
            if o['stop_on_nonmatch'] and not invert:
                if had_block and not is_match:
                    result.searched_line_count=idx+1
                    break
            if emit:
                had_block=True
                subs=[]
                if not invert:
                    for m in ms:
                        sb=byte_len_of(ln.content[:m.start()],model); eb=byte_len_of(ln.content[:m.end()],model)
                        subs.append(SubMatch(sb,eb,encode_internal(m.group(0),model),m,sb,ln.start+sb,idx))
                blocks.append(MatchBlock([idx],subs))
    result.blocks=blocks
    result.matched_lines=sum(len(b.line_indices) for b in blocks)
    result.matches=0 if invert else sum(len(b.subs) for b in blocks)
    # count value
    if true_multi and not invert: result.count_value=result.matches
    else: result.count_value=result.matched_lines
    # bytes searched
    if bmode=='binary' and prep.mmap_like and binary_offset is not None:
        result.bytes_searched=binary_offset
    elif result.searched_line_count<len(lines):
        # up to end of last searched line
        li=lines[result.searched_line_count-1]
        result.bytes_searched=li.start+len(li.raw)
    else:
        result.bytes_searched=len(data)
    result.elapsed=time.time()-t0
    return result

