# ---------- replacement ----------
def expand_replacement(template, match, matcher, model):
    # returns bytes
    out=[]
    def lit_bytes(s): return s.encode('utf-8','surrogateescape')
    def group_bytes(name):
        val=None
        if name.isdigit():
            idx=int(name)
            try: val=match.group(idx)
            except Exception: val=None
        else:
            if matcher and name in matcher.capture_names:
                py=matcher.capture_names[name][1]
                try: val=match.group(py)
                except Exception: val=None
        if val is None: return b''
        return encode_internal(val,model)
    i=0; lit=''
    def flush():
        nonlocal lit
        if lit: out.append(lit_bytes(lit)); lit=''
    while i<len(template):
        c=template[i]
        if c!='$': lit+=c; i+=1; continue
        if i+1>=len(template): lit+='$'; i+=1; continue
        n=template[i+1]
        if n=='$': lit+='$'; i+=2; continue
        if n=='{':
            j=template.find('}',i+2)
            if j==-1: lit+='$'; i+=1; continue
            name=template[i+2:j]
            flush(); out.append(group_bytes(name)); i=j+1; continue
        if n.isalnum() or n=='_':
            j=i+1; name=''
            while j<len(template) and (template[j].isalnum() or template[j]=='_'):
                name+=template[j]; j+=1
            flush(); out.append(group_bytes(name)); i=j; continue
        lit+='$'; i+=1
    flush()
    return b''.join(out)

# ---------- colors / hyperlinks ----------
class Style:
    def __init__(self): self.fg=None; self.bg=None; self.bold=False; self.intense=False; self.underline=False
    def reset(self): self.fg=None; self.bg=None; self.bold=False; self.intense=False; self.underline=False
    def has_any(self): return self.fg is not None or self.bg is not None or self.bold or self.intense or self.underline
    def ansi(self):
        out=[b'\x1b[0m']
        if self.bold: out.append(b'\x1b[1m')
        if self.underline: out.append(b'\x1b[4m')
        for attr,is_fg in ((self.fg,True),(self.bg,False)):
            if attr is None: continue
            kind=attr[0]
            if kind=='name':
                code=COLOR_NAMES[attr[1]]
                if self.intense:
                    out.append((f'\x1b[{38 if is_fg else 48};5;{8+code}m').encode())
                else:
                    out.append((f'\x1b[{(30 if is_fg else 40)+code}m').encode())
            elif kind=='256': out.append((f'\x1b[{38 if is_fg else 48};5;{attr[1]}m').encode())
            elif kind=='rgb':
                r,g,b=attr[1]; out.append((f'\x1b[{38 if is_fg else 48};2;{r};{g};{b}m').encode())
        return b''.join(out)

def build_styles(pa):
    styles={'path':Style(),'line':Style(),'column':Style(),'match':Style()}
    styles['path'].fg=('name','magenta'); styles['line'].fg=('name','green')
    styles['match'].fg=('name','red'); styles['match'].bold=True
    for typ,attr,val in pa.colors:
        st=styles[typ]
        if attr=='none': st.reset()
        elif attr=='fg': st.fg=val
        elif attr=='bg': st.bg=val
        elif attr=='style':
            if val=='bold': st.bold=True
            elif val=='nobold': st.bold=False
            elif val=='intense': st.intense=True
            elif val=='nointense': st.intense=False
            elif val=='underline': st.underline=True
            elif val=='nounderline': st.underline=False
    return styles

_HOSTNAME_CACHE=None
def get_hostname(pa):
    global _HOSTNAME_CACHE
    if _HOSTNAME_CACHE is not None: return _HOSTNAME_CACHE
    host=''
    hb=pa.o.get('hostname_bin')
    if hb:
        try:
            p=subprocess.run([hb],stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=5)
            txt=p.stdout.decode('utf-8','surrogateescape').strip()
            if txt: host=txt
        except Exception: pass
    if not host:
        try:
            import socket; host=socket.gethostname()
        except Exception: host=''
    _HOSTNAME_CACHE=host; return host

def hyperlink_url(fmt,pa,src,line_no,col_no):
    if not fmt or src.is_stdin or src.path is None: return None
    abspath=os.path.abspath(src.path)
    raw=fsb(abspath)
    safe=set(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789/-._~:@!$&'()*+,;=")
    enc=[]
    for byte in raw:
        if byte in safe or byte>=128: enc.append(chr(byte))
        else: enc.append('%%%02X'%byte)
    path=''.join(enc)
    if not path.startswith('/'): path='/'+path
    wsl=''
    if os.environ.get('WSL_DISTRO_NAME'): wsl='wsl$/'+os.environ['WSL_DISTRO_NAME']
    url=fmt.replace('{host}',get_hostname(pa)).replace('{path}',path).replace('{line}',str(line_no or 1)).replace('{column}',str(col_no or 1)).replace('{wslprefix}',wsl)
    return url.encode('utf-8','surrogateescape')

@dataclass
class DisplayCfg:
    with_filename: bool; heading: bool; line_number: bool
    colors: bool; styles: dict

class Printer:
    def __init__(self,pa,disp,matcher):
        self.pa=pa; self.o=pa.o; self.d=disp; self.matcher=matcher
        self.model=matcher.model if matcher else ('bytes' if pa.o['no_unicode'] else 'unicode')
        self.term=b'\x00' if pa.o['null_data'] else b'\n'
        self._printed_any_file=False
    # path helpers
    def path_bytes(self,src):
        p=src.out_path()
        if self.o['path_separator'] is not None:
            p=p.replace('/',self.o['path_separator'])
        return fsb(p)
    def colored(self,b,style_name):
        if not self.d.colors: return b
        st=self.d.styles[style_name]
        return st.ansi()+b+b'\x1b[0m'
    def match_colored(self,b):
        if not self.d.colors: return b
        st=self.d.styles['match']
        if not st.has_any(): return b
        return st.ansi()+b+b'\x1b[0m'
    def _link(self,src,line_no,col_no):
        if not self.d.colors or not self.o['hyperlink_format']: return (b'',b'')
        url=hyperlink_url(self.o['hyperlink_format'],self.pa,src,line_no,col_no)
        if url is None: return (b'',b'')
        return (b'\x1b]8;;'+url+b'\x1b\\', b'\x1b]8;;\x1b\\')
    def prefix(self,src,line_no,col_no,byte_off,is_context,include_path=True):
        # returns bytes prefix WITHOUT trailing separator for main content; caller handles hyperlink end position:
        # We build as: [linkstart path sep line sep col sep byteoff linkend sep] in one go here.
        o=self.o; sep=(o['field_context_separator'] if is_context else o['field_match_separator']).encode('utf-8','surrogateescape')
        fields=[]
        hyperlink_start=b''; hyperlink_end=b''
        if include_path and self.d.with_filename and not self.d.heading:
            hyperlink_start,hyperlink_end=self._link(src,line_no,col_no)
            if o['null']:
                return hyperlink_start+self.colored(self.path_bytes(src),'path')+hyperlink_end+b'\x00'+self._rest_fields(line_no,col_no,byte_off,is_context,sep,first=False)
            fields.append(self.colored(self.path_bytes(src),'path'))
        # heading mode or no filename: fields start with numbers
        body=self._rest_fields_from_list(fields,line_no,col_no,byte_off,is_context,sep)
        if hyperlink_start:
            # insert end before final separator (last sep added by _rest_fields_from_list if any field present)
            if body.endswith(sep) and sep!=b'':
                return hyperlink_start+body[:-len(sep)]+hyperlink_end+sep
            return hyperlink_start+body+hyperlink_end
        return body
    def _rest_fields(self,line_no,col_no,byte_off,is_context,sep,first=True):
        return self._rest_fields_from_list([],line_no,col_no,byte_off,is_context,sep,path_already=True)
    def _rest_fields_from_list(self,fields,line_no,col_no,byte_off,is_context,sep,path_already=False):
        o=self.o
        show_line=self.d.line_number or o['column'] or o['vimgrep']
        if show_line and line_no is not None:
            fields.append(self.colored(str(line_no).encode(),'line'))
        if o['column'] or o['vimgrep']:
            if col_no is not None: fields.append(self.colored(str(col_no).encode(),'column'))
        if o['byte_offset']:
            if byte_off is not None: fields.append(self.colored(str(byte_off).encode(),'column'))
        if not fields: return b''
        return sep.join(fields)+sep
    def write_heading(self,src,line_no=1,col_no=1):
        if self._printed_any_file:
            OUT.write(self.term)
        self._printed_any_file=True
        if self.d.with_filename:
            ls,le=self._link(src,line_no,col_no)
            if self.o['null']:
                OUT.write(ls+self.colored(self.path_bytes(src),'path')+le+b'\x00')
            else:
                OUT.write(ls+self.colored(self.path_bytes(src),'path')+le+self.term)
    def print_result_standard(self,result):
        src=result.src; o=self.o
        if result.suppressed: return
        if not result.blocks: return
        # binary message mode
        if result.binary_mode=='binary' and result.binary_offset is not None and not o['text']:
            # heading counts as a file for separation? In heading mode binary message is inline, separator before files handled by non-heading? We'll add blank line if heading and previous file.
            if self.d.heading and self._printed_any_file: OUT.write(self.term)
            self._printed_any_file=True
            msg=f'binary file matches (found "\\0" byte around offset {result.binary_offset})'.encode()
            if self.d.with_filename:
                ls,le=self._link(src,1,1)
                if o['null']:
                    OUT.write(ls+self.colored(self.path_bytes(src),'path')+le+b'\x00'+msg+self.term)
                else:
                    OUT.write(ls+self.colored(self.path_bytes(src),'path')+le+b': '+msg+self.term)
            else:
                OUT.write(msg+self.term)
            return
        if self.d.heading:
            self.write_heading(src)
        # chunks
        chunks=self._context_chunks(result)
        for ci,(start,end) in enumerate(chunks):
            if ci>0 and (o['before_context'] or o['after_context'] or o['passthru']):
                if o['context_separator'] is not None:
                    OUT.write(o['context_separator'].encode('utf-8','surrogateescape')+self.term)
            for li in range(start,end+1):
                block=self._block_for_line(result,li)
                if block is not None:
                    # Match line rendering needs to happen once per block when first line encountered if replace/vimgrep/only etc
                    if block.line_indices[0]!=li and (o['only_matching'] and not o['invert_match']):
                        continue
                    if o['only_matching'] and not o['invert_match']:
                        if li==block.line_indices[0]: self._print_only_matching(result,block)
                    elif o['vimgrep'] and not o['invert_match']:
                        if li==block.line_indices[0]: self._print_vimgrep(result,block)
                    else:
                        if li==block.line_indices[0] and o['replace'] is not None and not o['invert_match']:
                            self._print_replaced_block(result,block)
                        elif o['replace'] is not None and not o['invert_match']:
                            continue
                        else:
                            self._print_line(result,li,False,block)
                else:
                    self._print_line(result,li,True,None)
        if not self.d.heading: self._printed_any_file=True
    def _context_chunks(self,result):
        o=self.o
        maxline=min(result.searched_line_count,len(result.lines))
        if maxline==0: return []
        if o['passthru']:
            return [(0,maxline-1)]
        ranges=[]
        for b in result.blocks:
            s=max(0,b.line_indices[0]-o['before_context']); e=min(maxline-1,b.line_indices[-1]+o['after_context'])
            if ranges and s<=ranges[-1][1]+1: ranges[-1]=(ranges[-1][0],max(ranges[-1][1],e))
            else: ranges.append((s,e))
        return ranges
    def _block_for_line(self,result,li):
        for b in result.blocks:
            if li in b.line_indices: return b
        return None
    def _block_column(self,result,block):
        if not block.subs: return 1
        s=block.subs[0]
        return s.start_byte_line+1
    def _line_sub_segments(self,result,block,li):
        # return list of (start_byte_in_content,end_byte) highlights for this line
        segs=[]; ln=result.lines[li]
        if block is None: return segs
        for s in block.subs:
            abs_start=s.abs_byte; abs_end=s.abs_byte+(s.end_byte_block-s.start_byte_block)
            # For true multiline s.start/end block are relative to block start bytes incl terms; abs computed at creation as match byte start and length from block offsets may include \n bytes length in group - correct in bytes
            los=max(abs_start,ln.start); hie=min(abs_end,ln.start+len(ln.content_bytes))
            if hie>los: segs.append((los-ln.start,hie-ln.start))
            elif los==hie and abs_start>=ln.start and abs_start<=ln.start+len(ln.content_bytes):
                segs.append((los-ln.start,hie-ln.start))
        return segs
    def _styled_content(self,content,segs):
        if not self.d.colors or not segs: return content
        out=[]; pos=0
        for a,b in sorted(segs):
            if a<pos: a=pos
            if a>pos: out.append(content[pos:a])
            if b>a: out.append(self.match_colored(content[a:b])); pos=b
            elif b==a: pos=a
        if pos<len(content): out.append(content[pos:])
        return b''.join(out)
    def _trim(self,content):
        if not self.o['trim']: return content,0
        i=0
        while i<len(content) and content[i:i+1] in (b' ',b'\t'): i+=1
        return content[i:],i
    def _print_line(self,result,li,is_context,block):
        src=result.src; ln=result.lines[li]; o=self.o
        content=ln.content_bytes
        content,trimn=self._trim(content)
        segs=[]
        if not is_context and block is not None:
            rawsegs=self._line_sub_segments(result,block,li)
            for a,b in rawsegs:
                aa=max(a-trimn,0); bb=max(b-trimn,0)
                if bb>=aa: segs.append((aa,bb))
        # max columns
        display=self._apply_max_columns(content,is_context,block,segs)
        line_no=li+1; col=self._block_column(result,block) if block is not None else 1
        byteoff=ln.start
        pref=self.prefix(src,line_no,col,byteoff,is_context)
        term=ln.raw[len(ln.content_bytes):] if len(ln.raw)>len(ln.content_bytes) else self.term
        # if term came from raw it might be b'\n' or b'\x00'; when display is omitted msg, printer still uses term
        OUT.write(pref+display+term)
    def _apply_max_columns(self,content,is_context,block,segs):
        o=self.o; M=o['max_columns']
        if not M or len(content)<=M:
            return self._styled_content(content,segs)
        if o['replace'] is not None and not is_context and block is not None:
            # (replace blocks take other path mostly)
            n=len(block.subs) if block else 0
            return f'[Omitted long line with {n} matches]'.encode()
        if o['max_columns_preview']:
            preview=content[:M]
            psegs=[(a,min(b,M)) for a,b in segs if a<M]
