# ---------- config / main ----------
def read_config_args(raw_argv):
    if '--no-config' in raw_argv: return []
    path=os.environ.get('RIPGREP_CONFIG_PATH')
    if not path: return []
    try:
        with open(path,'rb') as f: data=f.read()
    except OSError as e:
        if os.path.isdir(path):
            eprint_msg(f"rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {os_error_str(e)}\n".encode('utf-8','surrogateescape'))
        else:
            eprint_msg(f"rg: failed to read the file specified in RIPGREP_CONFIG_PATH: {path}: {os_error_str(e)}\n".encode('utf-8','surrogateescape'))
        return []
    args=[]
    text=data.decode('utf-8','surrogateescape')
    for line in text.split('\n'):
        t=line.strip()
        if not t or t.startswith('#'): continue
        args.append(t)
    return args

def _version_long():
    # detect simd runtime from cpuinfo
    flags=''
    try:
        with open('/proc/cpuinfo') as f: flags=f.read()
    except Exception: pass
    def has(f): return f" {f} " in flags or f" {f}\n" in flags
    sse2='+SSE2' if has('sse2') else '-SSE2'
    ssse3='+SSSE3' if has('ssse3') else '-SSSE3'
    avx2='+AVX2' if has('avx2') else '-AVX2'
    return (f"{VERSION}\n\nfeatures:-pcre2\nsimd(compile):+SSE2,-SSSE3,-AVX2\nsimd(runtime):{sse2},{ssse3},{avx2}\n\nPCRE2 is not available in this build of ripgrep.\n").encode()

def stdin_is_searchable():
    try:
        mode=os.fstat(0).st_mode
    except Exception: return False
